function Trie(){ this.root={children:{}, end:false}; }
Trie.prototype.insert=function(w){ var node=this.root; for(var i=0;i<w.length;i++){ var c=w[i]; if(!node.children[c]) node.children[c]={children:{}, end:false}; node=node.children[c]; } node.end=true; };
Trie.prototype.search=function(w){ var node=this.root; for(var i=0;i<w.length;i++){ if(!node.children[w[i]]) return false; node=node.children[w[i]]; } return node.end; };
Trie.prototype.startsWith=function(p){ var node=this.root; for(var i=0;i<p.length;i++){ if(!node.children[p[i]]) return false; node=node.children[p[i]]; } return true; };
function makeTrie(){ return new Trie(); }
var EXPORTS={makeTrie:makeTrie};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.PrefixTreeForgePure = EXPORTS; }
